(async()=>{let items=PRODUCTS,index=0,minimized=false;try{items=(await WildRideMember.request('catalog')).products}catch{/* Static display catalog remains available before cloud migration. */}items=items.filter(p=>p.featured&&p.active!==false).sort((a,b)=>(a.ad_order??100)-(b.ad_order??100)||a.id.localeCompare(b.id));if(!items.length)return;const signature=items.map(p=>p.id+':'+p.revision).join('|');try{if(sessionStorage.getItem('wildride-home-ad-dismissed')===signature)return}catch{}const key='wildride-home-ad-collapsed',el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};try{minimized=sessionStorage.getItem(key)==='1'}catch{}const widget=el('aside',undefined,'floating-product-ad');widget.setAttribute('aria-label','馭野嚴選精選商品');const toggle=el('button','馭野嚴選・精選推薦 ＋','ad-toggle');toggle.type='button';const card=el('div',undefined,'ad-card'),head=el('div',undefined,'ad-header'),brand=el('b','WILDRIDE SELECT'),close=el('button','×','ad-close');close.type='button';close.setAttribute('aria-label','關閉本次商品廣告');const minimize=el('button','−','ad-close');minimize.type='button';minimize.setAttribute('aria-label','縮小商品廣告');head.append(brand,minimize,close);const link=el('a',undefined,'ad-image-link'),image=el('img');image.width=240;image.height=190;link.append(image);const copy=el('div',undefined,'ad-copy'),category=el('small'),title=el('h3'),price=el('p',undefined,'ad-price'),note=el('p','展示價，非免費；詳情另行公告。','ad-note'),cta=el('a','查看課程／活動 ↗','ad-cta'),navigation=el('div',undefined,'ad-navigation'),prev=el('button','←'),position=el('span'),next=el('button','→');for(const [b,label]of [[prev,'上一項推薦'],[next,'下一項推薦']]){b.type='button';b.setAttribute('aria-label',label)}navigation.append(prev,position,next);copy.append(category,title,price,note,cta,navigation);card.append(head,link,copy);widget.append(toggle,card);document.body.append(widget);
function render(){const p=items[index],href='shop.html?product='+encodeURIComponent(p.id)+'#catalog';image.src=p.image;image.alt=p.name+'展示圖片';link.href=cta.href=href;category.textContent=p.group+' / '+p.category;title.textContent=p.name;price.textContent='NT$'+Number(p.price).toLocaleString('zh-TW');cta.textContent=['課程類','活動類'].includes(p.group)?'查看課程／活動 ↗':'查看商品 ↗';position.textContent=(index+1)+' / '+items.length;navigation.hidden=items.length<2;card.hidden=minimized;toggle.hidden=!minimized;toggle.setAttribute('aria-expanded',String(!minimized))}function collapse(value){minimized=value;try{sessionStorage.setItem(key,value?'1':'0')}catch{}render();(value?toggle:close).focus()}minimize.onclick=()=>collapse(true);close.onclick=()=>{try{sessionStorage.setItem('wildride-home-ad-dismissed',signature)}catch{}widget.remove()};toggle.onclick=()=>collapse(false);prev.onclick=()=>{index=(index+items.length-1)%items.length;render()};next.onclick=()=>{index=(index+1)%items.length;render()};render()})();
